import {prioritizeDebts,compareBalanceTransfer,loanPayment} from './debt-calculations.js';
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(label,key,value,min=0,max=100000,step=1)=>`<label class="field"><span>${label}</span><input type="number" data-value="${key}" value="${value}" min="${min}" max="${max}" step="${step}" aria-label="${label}"></label>`;
const status=(r,money)=>r.error?`<p class="banner">${safe(r.error)}</p>`:`<div class="stats"><div class="stat">Debt-free in<strong>${r.months} months</strong></div><div class="stat warn">Interest<strong>${money(r.interest)}</strong></div><div class="stat">Total payments<strong>${money(r.totalPaid)}</strong></div></div>`;
const sourceFooter='<p class="fineprint">Sources: FCAC, Paying back your debt; Debt consolidation; How credit cards work. All balances, rates and fees in these exercises are fictional and editable.</p>';
export function renderDebtActivity(name,a,money){
 money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
 if(name==='debtplan'){
  const defaults={cardBalance:5000,cardApr:20,cardMin:150,lineBalance:8000,lineApr:9,lineMin:120,smallBalance:1000,smallApr:12,smallMin:50,extra:200};
  const v={...defaults,...a};const debts=[{id:'card',name:'Credit card',balance:v.cardBalance,apr:v.cardApr,minPayment:v.cardMin},{id:'line',name:'Line of credit',balance:v.lineBalance,apr:v.lineApr,minPayment:v.lineMin},{id:'small',name:'Small loan',balance:v.smallBalance,apr:v.smallApr,minPayment:v.smallMin}];
  const avalanche=prioritizeDebts(debts,v.extra,'avalanche'),snowball=prioritizeDebts(debts,v.extra,'snowball');
  return `<div class="activity"><div class="activity-head"><strong>Choose the target, keep the budget</strong><span>Avalanche vs snowball</span></div><div class="activity-content"><div class="lab-prompt">Pay every required minimum first. Then decide where the extra money goes. Both strategies use the same total monthly budget and roll freed payments into the remaining debt.</div>${[['Credit card','card'],['Line of credit','line'],['Small loan','small']].map(([label,k])=>`<details ${k==='card'?'open':''}><summary style="cursor:pointer;font-weight:700;font-size:13px;margin:18px 0">${label}</summary>${field(label+' balance ($)',k+'Balance',v[k+'Balance'],0,1000000)}${field(label+' annual APR (%)',k+'Apr',v[k+'Apr'],0,60,.1)}${field(label+' fixed monthly minimum ($)',k+'Min',v[k+'Min'],0,100000,.01)}</details>`).join('')}${field('Extra monthly payment above all minimums ($)','extra',v.extra,0,100000,.01)}<div class="debt-results"><div class="lab-insight"><strong>Total monthly budget: ${money(avalanche.budget??debts.reduce((s,d)=>s+d.minPayment,0)+v.extra)}</strong><p>High-interest debt first targets the highest APR. Smallest-balance first targets quick wins. Past-due amounts, essential bills and secured-debt risks may need attention before either strategy.</p></div><h3 style="font-size:15px">Avalanche · highest APR first</h3>${status(avalanche,money)}${!avalanche.error?`<p class="fineprint">Payoff order: ${avalanche.order.map(o=>`${safe(o.name)} (month ${o.month})`).join(' → ')||'No debt outstanding.'}</p>`:''}<h3 style="font-size:15px;margin-top:23px">Snowball · smallest balance first</h3>${status(snowball,money)}${!snowball.error?`<p class="fineprint">Payoff order: ${snowball.order.map(o=>`${safe(o.name)} (month ${o.month})`).join(' → ')||'No debt outstanding.'}</p>`:''}${!avalanche.error&&!snowball.error?`<div class="lab-insight"><strong>${money(Math.abs(snowball.interest-avalanche.interest))} interest difference</strong><p>${Math.abs(snowball.interest-avalanche.interest)<.01?'These inputs produce essentially the same interest cost.':avalanche.interest<snowball.interest?'The avalanche costs less interest in this model.':'These payment constraints produce a lower cost for the snowball in this example.'} Motivation matters too; a plan must remain affordable and keep required payments on time.</p></div>`:''}</div><p class="fineprint">Teaching model: monthly interest at APR ÷ 12 before payment; fixed entered minimums, capped at amount owed. Minimums on every active debt are paid first; leftover budget targets one debt at a time. The original total budget continues after debts close. Final payments are capped. No new spending, fees, rate changes or penalties. Actual minimums and daily interest vary. A 100-year cap prevents indefinite projections. A temporary increase in one balance can occur if its minimum is below interest.</p>${sourceFooter}</div></div>`;
 }
 if(name==='transfer'){
  const balance=a.balance??5000,currentApr=a.currentApr??20,payment=a.payment??250,promoApr=a.promoApr??0,promoMonths=a.promoMonths??12,feePercent=a.feePercent??3,postApr=a.postApr??22;
  const r=compareBalanceTransfer({balance,currentApr,payment,promoApr,promoMonths,feePercent,postApr});
  return `<div class="activity"><div class="activity-head"><strong>A low rate can have an expiry date</strong><span>Compare the entire payoff</span></div><div class="activity-content"><div class="lab-prompt">Try a smaller payment or shorter promotion. Does the balance disappear before the introductory rate ends? What if the new ongoing rate is higher?</div>${field('Balance to transfer ($)','balance',balance,0,1000000)}${field('Current annual APR (%)','currentApr',currentApr,0,60,.1)}${field('Fixed monthly payment ($)','payment',payment,1,100000,.01)}${field('Promotional annual APR (%)','promoApr',promoApr,0,60,.1)}${field('Promotion length (months)','promoMonths',promoMonths,0,60)}${field('Transfer fee (%)','feePercent',feePercent,0,20,.1)}${field('Annual APR after promotion (%)','postApr',postApr,0,60,.1)}<div class="debt-results">${r.error?`<div class="banner">${safe(r.error)}</div>`:`<div class="lab-insight"><strong>Transfer fee added to the debt: ${money(r.fee)}</strong><p>The new balance starts at ${money(balance+r.fee)}. In this exercise the fee receives the same interest treatment as the transferred balance. Actual issuer terms may differ.</p></div><h3 style="font-size:15px">Keep the existing balance</h3>${status(r.existing,money)}<h3 style="font-size:15px;margin-top:24px">Transfer, then use the ongoing rate</h3>${status(r.transfer,money)}<div class="stats"><div class="stat">Balance after promo month ${promoMonths}<strong>${money(r.transfer.balanceAtPromo??0)}</strong></div><div class="stat">${r.transfer.error?'Interest accrued so far + fee':'Interest + transfer fee'}<strong>${money(r.transfer.interest+r.fee)}</strong></div><div class="stat ${r.savings!==null&&r.savings>=0?'good':'warn'}">Modelled total-cost ${r.savings!==null&&r.savings<0?'increase':'saving'}<strong>${r.savings===null?'Not comparable':money(Math.abs(r.savings))}</strong></div></div>`}</div><p class="fineprint">Monthly interest = APR ÷ 12, added before each fixed payment; the promotional rate applies for exactly the entered number of payments, then the post-promo rate applies. Transfer fee is financed upfront. No new purchases, annual fees, daily accrual, different payment allocation, late fees or offer cancellation. Eligibility, transfer limits and deadlines vary. A missed payment may end a promotional rate. Paying only a promotional balance can affect how new purchases accrue interest—read the agreement. The full-payoff comparison includes the fee, so a 0% offer is not automatically free.</p>${sourceFooter}</div></div>`;
 }
 if(name==='loan'){
  const amount=a.amount??30000,apr=a.apr??7,months=a.termMonths??60,type=a.loanType??'standard',stressApr=a.stressApr??10,ongoing=a.ongoing??300;
  const base=loanPayment({amount,apr,months,type}),stress=loanPayment({amount,apr:stressApr,months,type});
  return `<div class="activity"><div class="activity-head"><strong>Borrow for a purchase, see the whole cost</strong><span>Payment ≠ affordability</span></div><div class="activity-content"><div class="lab-prompt">Extend the repayment period. The monthly payment may fall while the total interest rises. Then try a higher rate and add the costs of owning the thing.</div><label class="field"><span>Interest convention</span><select data-choice="loanType" aria-label="Interest convention"><option value="standard" ${type==='standard'?'selected':''}>Simple loan model</option><option value="mortgage" ${type==='mortgage'?'selected':''}>Fixed Canadian mortgage model</option></select></label>${field('Amount borrowed after down payment ($)','amount',amount,0,5000000)}${field('Quoted annual interest rate (%)','apr',apr,0,40,.1)}${field('Full repayment / amortization (months)','termMonths',months,1,600)}${field('Higher-rate scenario (%)','stressApr',stressApr,0,40,.1)}${field('Other monthly ownership costs ($)','ongoing',ongoing,0,100000,.01)}<div class="debt-results">${base.error?`<div class="banner">${safe(base.error)}</div>`:`<div class="stats"><div class="stat">Monthly loan payment<strong>${money(base.payment)}</strong></div><div class="stat warn">Interest over full repayment<strong>${money(base.interest)}</strong></div><div class="stat">Total principal + interest<strong>${money(base.total)}</strong></div></div><div class="lab-insight"><strong>Loan payment + other monthly costs: ${money(base.payment+ongoing)}</strong><p>At ${stressApr}% throughout the same repayment period, the illustrative payment becomes ${money(stress.payment??0)}; with other costs, ${money((stress.payment??0)+ongoing)}. This compares two rate scenarios from the start, not an actual mortgage-renewal schedule or approval test.</p></div><div class="table-scroll"><table><thead><tr><th>Remember the extra costs</th><th>Examples</th></tr></thead><tbody><tr><th>Vehicle</th><td>Insurance, fuel/charging, repairs, registration, parking and depreciation.</td></tr><tr><th>Home</th><td>Property tax, insurance, utilities, condo fees, repairs, closing costs and possible mortgage insurance.</td></tr><tr><th>Terms</th><td>Down payment, financed fees, prepayment rights, renewal rates and penalties can change the comparison.</td></tr></tbody></table></div>`}</div><p class="fineprint">${type==='mortgage'?'Mortgage model: monthly rate = (1 + quoted annual rate ÷ 2)^(1/6) − 1, reflecting nominal semi-annual compounding.':'Simple loan model: monthly rate = annual rate ÷ 12.'} Payments occur monthly at month-end; the stated rate stays fixed over the entire entered amortization, including in the mortgage illustration. A mortgage term is the contract/rate period; amortization is the full repayment schedule, so actual renewal rates can change total cost. No taxes, insurance premiums, origination fees, balloon payments, variable-rate resets or penalties are financed automatically. Input the amount borrowed after down payment and include any known financed charges yourself. This is not a mortgage qualification result.</p>${sourceFooter}</div></div>`;
 }
 return null;
}
